import{_ as o,l as i,o as t,c as l,v as e,p as s,x as r,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"有效价差与实现价差","description":"","frontmatter":{"title":"有效价差与实现价差","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/effective-realized-spread.md","filePath":"quant/effective-realized-spread.md","lastUpdated":1789023840000}'),u={name:"quant/effective-realized-spread.md"};function h(c,a,_,m,P,B){const n=i("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="有效价差与实现价差" tabindex="-1">有效价差与实现价差 <a class="header-anchor" href="#有效价差与实现价差" aria-label="Permalink to &quot;有效价差与实现价差&quot;">​</a></h1><div class="epigraph"><p>报价价差是挂在簿上的宽度；有效价差是成交相对中点实际付了多少；实现价差是做市商把这笔存货再转手之后还剩多少。</p><footer>—— Huang and Stoll, Dealer versus Auction Markets: A Paired Comparison of Execution Costs on NASDAQ and the NYSE, Journal of Financial Economics 1996</footer></div><p><a href="/quant/vpin">上一课</a>把 PIN 的不平衡搬到成交量时钟：等体积桶、批量分类、滚动绝对不平衡比；它测流量毒性，不要读成 EKOP 意义下的知情概率。<a href="/quant/spread-decomposition">价差分解</a>给出了会计，<a href="/quant/roll-model">Roll</a> 给出了只用成交价的隐含测度。缺口是把执行成本接到成交上：有效价差是成交相对中点实际付了多少，实现价差是做市商转手之后还剩多少。本课写这一对定义，不重推 VPIN 的桶长。它测的是已经发生的成交有多贵，不是生成模型里的知情概率。后课 Lee–Ready 默认：方向 \\(D\\) 必须先定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>报价价差 \\(A-B\\) 是对外宣布的一轮往返成本。实际成交价 \\(P\\) 往往在价差内部。对主动方，真正付的是 \\(P\\) 相对当时中点 \\(M=(A+B)/2\\) 的距离。对被动方，这笔单变成存货之后中点会动。若只报告报价价差，竞价市场与做市商市场无法比；若只报告有效价差，又看不到事后冲击。缺口是一套符号一致、可按成交加总的定义，并把冲击从实现利润里分开。</p><h3 id="方向-必须先定义" tabindex="-1">方向 \\(D\\) 必须先定义 <a class="header-anchor" href="#方向-必须先定义" aria-label="Permalink to &quot;方向 $D$ 必须先定义&quot;">​</a></h3><p>所有价差公式都乘以成交方向 \\(D\\)：主动买 \\(+1\\)，主动卖 \\(-1\\)。没有 \\(D\\)，\\((P-M)\\) 的符号无意义。Lee–Ready 用成交价相对中点，平价时用 tick 检验。方向错误会把有效价差系统性压低（随机分类使 \\(D(P-M)\\) 期望变小）。高频、多交易所、中点延迟一毫秒，分类错误率就不是可以忽略的边角。</p><p><span class="marginnote">有效价差不是「成交价减买一」。买一是被动卖的报价，主动买成交可能发生在卖一、卖二甚至中点。中点是当时公开买卖的中心，用来当未受本笔成交污染的参考价——前提是报价时间戳与成交时间戳对齐。错配毫秒，中点就可能已经含了本笔。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记成交价 \\(P_t\\)、同时刻（或紧前）中点 \\(M_t\\)、方向 \\(D_t\\)。<strong>有效价差</strong></p> \\[\\mathrm{ES}_t=2D_t(P_t-M_t). \\]<p>乘 2 是为了与报价价差同量纲：一轮买加一轮卖。单笔主动买若在卖价成交且没有改善，有效价差等于报价价差；若有价格改善，有效价差更小，甚至为负（成交越过中点，在对方一侧）。</p><p>取滞后 \\(\\tau\\)（五分钟、十五分钟、或下一笔报价更新），<strong>实现价差</strong></p> \\[\\mathrm{RS}_t=2D_t(P_t-M_{t+\\tau}). \\]<p>它把参考价换成未来中点：被动方若以 \\(P_t\\) 买入（对应主动卖，\\(D_t=-1\\)），之后中点下跌，实现价差变负。Huang–Stoll 把<strong>价格冲击</strong>写成有效减实现：</p> \\[\\mathrm{ES}_t-\\mathrm{RS}_t=2D_t(M_{t+\\tau}-M_t). \\]<p>即方向乘以后续中点变动。冲击大，说明成交后价格顺着主动方走，通常解释为逆向选择或持久的存货压力。实现价差则更接近做市商扣除冲击后的利润：报价价差里的订单处理与存货成分。</p><h3 id="的选择改变成分而不改变会计恒等式" tabindex="-1">\\(\\tau\\) 的选择改变成分而不改变会计恒等式 <a class="header-anchor" href="#的选择改变成分而不改变会计恒等式" aria-label="Permalink to &quot;$\\tau$ 的选择改变成分而不改变会计恒等式&quot;">​</a></h3><p>恒等式 \\(\\mathrm{ES}=\\mathrm{RS}+\\mathrm{Impact}\\) 对任意 \\(\\tau\\) 成立。\\(\\tau\\) 太短，冲击尚未实现，实现价差偏高、冲击偏低；\\(\\tau\\) 太长，不相关信息进入 \\(M_{t+\\tau}\\)，冲击方差变大，均值仍可解释为持久成分。五分钟是美股文献的常见折中，不是定理。开盘、收盘、宏观发布前后，\\(\\tau\\) 应缩短到与信息释放匹配的尺度。跨市场比较必须锁定同一 \\(\\tau\\)、同一方向算法、同一是否对成交量加权。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效价差捕捉的是<strong>相对公开中点的即时偏离</strong>。限价簿足够深、市价单只扫一档时，它接近报价价差；冰山、暗池、零售内化会把大量成交推进价差内部，有效价差小于报价价差。实现价差捕捉的是<strong>这笔成交作为存货的事后盯市</strong>。若对手是非知情、随后中点随机游走，实现价差的期望约等于有效价差；若对手知情，中点漂移，实现价差被压缩。</p><p>这与 Huang–Stoll（1997）把价差拆成逆向选择、存货、订单处理三块是同一套会计：有效与实现提供不需要完整参数模型的约化统计量。Roll 模型用收益序列协方差估价差，吃的是收盘价，看不见盘中改善；本篇这组度量吃的是带方向的成交，分辨率高得多，也对数据质量苛求得得多。</p><p><span class="marginnote">加权方式会改变故事。等权有效价差突出小单；成交量加权、成交额加权才接近机构实际付的成本。大单拆成多笔时，应按父单聚合再算一个有效价差，否则会把扫档过程拆成许多「看起来很便宜」的子笔。</span></p><h3 id="与-pin、vpin-的分工" tabindex="-1">与 PIN、VPIN 的分工 <a class="header-anchor" href="#与-pin、vpin-的分工" aria-label="Permalink to &quot;与 PIN、VPIN 的分工&quot;">​</a></h3><p>PIN 回答生成过程里知情交易的概率，VPIN 回答成交量时钟上的流量毒性，有效/实现价差回答<strong>已经成交的那一笔有多贵、贵在冲击还是价差租金</strong>。毒性高的时段，冲击成分应上升、实现价差下降——这是联合检验，不是互相定义。不要用 PIN 替代有效价差去给交易台报成本，也不要用实现价差替代 PIN 去做信息风险的横截面。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>公式假设存在可观测的买卖报价与中点。集合竞价只有成交价，没有连续中点，有效价差要另定义参考价（例如开盘前的虚拟中点，或不用开盘笔）。涨跌停时一侧报价缺失，中点失真。盘后、暗池成交若没有同步的公开中点，应标成缺失而不是拿过期中点硬算。</p><p>不要把负的有效价差一律当数据错误：中点穿越、零售价格改善、收盘拍卖的交叉都可以产生负值。不要把实现价差当成做市商的会计利润：还有手续费、返佣、存货隔夜、对冲成本。\\(\\tau\\) 跨越隔夜时，实现价差混入<a href="/quant/calendar-overnight">隔夜收益</a>，应分开报告。方向分类应在清洗后的成交上做，先经过 <a href="/quant/tick-cleaning">Tick 数据清洗</a> 与 <a href="/quant/outlier-trades">异常成交</a>，否则错价会以巨大的 \\(P-M\\) 主导均值。</p><p><span class="marginnote">Huang–Stoll 1996 的配对比较依赖当时 NASDAQ 的做市商结构与纽交所的专家制度。今日的电子限价簿、零售内化、拍卖机制不同，公式仍可用，制度解释不能照抄「做市商市场更贵」那一句结论。</span></p>',29)),(t(),s(E,null,{default:r(()=>[d(n,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8A%A5%E4%BB%B7%20A%2CB%20%E2%86%92%20%E4%B8%AD%E7%82%B9%20M%22%5D%20--%3E%20ES%5B%22%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%202D(P-M)%22%5D%0A%20%20P%5B%22%E6%88%90%E4%BA%A4%E4%BB%B7%20P%2C%20%E6%96%B9%E5%90%91%20D%22%5D%20--%3E%20ES%0A%20%20P%20--%3E%20RS%5B%22%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%202D(P-M_%CF%84)%22%5D%0A%20%20M2%5B%22%E6%9C%AA%E6%9D%A5%E4%B8%AD%E7%82%B9%20M_%CF%84%22%5D%20--%3E%20RS%0A%20%20ES%20--%3E%20IMP%5B%22%E5%86%B2%E5%87%BB%20%3D%20ES%20%E2%88%92%20RS%20%3D%202D(M_%CF%84%E2%88%92M)%22%5D%0A%20%20RS%20--%3E%20IMP%0A%20%20IMP%20--%3E%20ADV%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%20%2F%20%E6%8C%81%E4%B9%85%E5%86%B2%E5%87%BB%22%5D%0A%20%20RS%20--%3E%20RENT%5B%22%E5%81%9A%E5%B8%82%E7%A7%9F%E9%87%91%20%2F%20%E4%B8%B4%E6%97%B6%E6%88%90%E5%88%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报价价差是挂牌宽度；有效价差 \\(2D(P-M)\\) 是成交相对当时中点的成本；实现价差 \\(2D(P-M_{τ})\\) 是对照未来中点后被动方还剩的价差。</li><li>价格冲击等于有效减实现，即方向乘中点漂移，约化地对应逆向选择。</li><li>\\(\\tau\\)、方向分类、成交量加权决定水平与排序；跨市场比较必须锁口径。</li><li>负有效价差可以是改善而不是错价；隔夜、停牌、无报价时段要单独处理。</li><li>与 PIN/VPIN 分工：成本会计对生成概率，二者联合看毒性是否真的让冲击变贵。</li><li>出处：Huang and Stoll, <em>Dealer versus Auction Markets</em>, Journal of Financial Economics 1996；价差成分的参数分解见 Huang and Stoll, Journal of Finance 1997。</li></ul>',2))])}const D=o(u,[["render",h]]);export{f as __pageData,D as default};
